head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vIrSeq;
scwin.vCurDate;
scwin.readDate;
scwin.vScrenID = "ULDSTF30303.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_single_read = function() {
    url = "/IRMgt.do?method=readIRInfo&inputMessageId=BIZSPT_INFO_INOUT&outputMessageId=BIZSPT_INFO_INOUT" + "&IR_SEQ=" + scwin.vIrSeq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_registerIRDateSet.DataID = encodeURI(url);
    dts_registerIRDateSet.reset();
};
scwin.fn_update = function() {
    if (title.getValue() == "") {
        $c.win.alert("[제목]을 입력하세요.");
        title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(title, 200, "제목")) {
        title.setValue("");
        title.focus();
        return false;
    }
    if (txb_com_abbrv.getValue() == "") {
        $c.win.alert("[법인명/코드]를 입력하세요.");
        txb_com_abbrv.focus();
        return;
    }
    if (txb_isur_cd.getValue() == "") {
        $c.win.alert("[법인명/코드]를 입력하세요.");
        txb_com_abbrv.focus();
        return;
    }
    if (ceo_nm.getValue() == "") {
        $c.win.alert("[대표이사]를 입력하세요.");
        ceo_nm.focus();
        return;
    }
    if (!scwin.checkMaxLength1(ceo_nm, 100, "대표이사")) {
        ceo_nm.setValue("");
        ceo_nm.focus();
        return false;
    }
    if (edt_Date.getValue() == "") {
        $c.win.alert("[IR일자]를 선택하세요.");
        edt_Date.focus();
        return;
    }
    // 2008/09/29 공시제도팀 김재홍대리 요청으로 날짜 입력제한 주석처리(YSH)
    /*
    if(dateCheck() == false){
    	return;
    }
    */
    if ($c.cp.valueOfIndex(hld_strt_tm_h, "VALUE", hld_strt_tm_h.getSelectedIndex()) == "") {
        $c.win.alert("[IR개최시작시간]를 선택하세요.");
        hld_strt_tm_h.focus();
        return;
    }
    if ($c.cp.valueOfIndex(hld_strt_tm_m, "VALUE", hld_strt_tm_m.getSelectedIndex()) == "") {
        $c.win.alert("[IR개최시작시간]를 선택하세요.");
        hld_strt_tm_m.focus();
        return;
    }
    if ($c.cp.valueOfIndex(hld_end_tm_h, "VALUE", hld_end_tm_h.getSelectedIndex()) != "" && $c.cp.valueOfIndex(hld_end_tm_m, "VALUE", hld_end_tm_m.getSelectedIndex()) != "") {
        if (scwin.timeCheck() == false) {
            hld_end_tm_m.focus();
            return;
        }
    }
    if (hld_loc.getValue() == "") {
        $c.win.alert("[개최장소]를 입력하세요.");
        hld_loc.focus();
        return;
    }
    if (!scwin.checkMaxLength1(hld_loc, 200, "개최장소")) {
        hld_loc.setValue("");
        hld_loc.focus();
        return false;
    }
    if (ir_chrg_nm.getValue() == "") {
        $c.win.alert("[담당자 성명]를 입력하세요.");
        ir_chrg_nm.focus();
        return;
    }
    if (!scwin.checkMaxLength1(ir_chrg_nm, 80, "담당자 성명")) {
        ir_chrg_nm.setValue("");
        ir_chrg_nm.focus();
        return false;
    }
    if (ir_chrg_tel_no.getValue() == "") {
        $c.win.alert("[담당자 전화번호]를 입력하세요.");
        ir_chrg_tel_no.focus();
        return;
    }
    if (!$c.cm.isNumber(ir_chrg_tel_no.getValue())) {
        $c.win.alert("[담당자 전화번호]를 숫자로 입력해주세요.");
        ir_chrg_tel_no.setValue("");
        ir_chrg_tel_no.focus();
        return;
    }
    if (!scwin.checkMaxLength1(ir_chrg_tel_no, 20, "담당자 전화번호")) {
        ir_chrg_tel_no.setValue("");
        ir_chrg_tel_no.focus();
        return false;
    }
    if (ir_chrg_email.getValue() == "") {
        $c.win.alert("[담당자 이메일]를 입력하세요.");
        ir_chrg_email.focus();
        return;
    }
    if (!scwin.checkMaxLength1(ir_chrg_email, 100, "담당자 이메일")) {
        ir_chrg_email.setValue("");
        ir_chrg_email.focus();
        return false;
    }
    var a = ir_chrg_email.getValue().indexOf('@');
    if (a <= 0 || a == ir_chrg_email.getValue().length - 1) {
        $c.win.alert("Email은 [id@krx.co.kr] 등의 형태로 입력하셔야 합니다.");
        ir_chrg_email.setValue("");
        ir_chrg_email.focus();
        return;
    }
    if (!scwin.checkMaxLength2(remk, 2000, "비고")) {
        remk.text = "";
        remk.focus();
        return false;
    }
    var rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        trs_Update.Action = "/IRMgt.do?method=modifyIRInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Update.KeyName = "toinb_dataid4";
        trs_Update.KeyValue = "JSP(I:pInput=dts_registerIRDateSet)";
        trs_Update.Post();
    }
};
