scwin.fn_delete = function() {
    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_registerIRDateSet.insertRow();
        dts_registerIRDateSet.setCellData(2, "IR_SEQ", dts_registerIRDateSet.getCellData(1, "IR_SEQ"));
        trs_delete.Action = "/IRMgt.do?method=removeIRInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_delete.KeyName = "toinb_dataid4";
        trs_delete.KeyValue = "JSP(I:pInput=dts_registerIRDateSet)";
        trs_delete.Post();
    }
};
scwin.fn_SetHeader = function() {
    // CUD용 Header
    dts_registerIRDateSet.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_INFO_INOUT";
    dts_registerIRDateSet.Reset();
    dts_registerIRDateSet.insertRow();
};
scwin.alert_error = function() {
    // gauce error
    var errorCount = dts_registerIRDateSet.SrvErrCount("INTERNAL");
    var i;
    for (i = 0; i < errorCount; i++) {
        $c.win.alert("[CODE: " + dts_registerIRDateSet.SrvErrCode("INTERNAL", i) + "] " + dts_registerIRDateSet.SrvErrMsg("INTERNAL", i));
    }

    // default error
    var errorCount = dts_registerIRDateSet.SrvErrCount("UNDEFINED");
    var i;
    for (i = 0; i < errorCount; i++) {
        $c.win.alert("[CODE: " + dts_registerIRDateSet.SrvErrCode("UNDEFINED", i) + "] " + dts_registerIRDateSet.SrvErrMsg("UNDEFINED", i));
    }

    // app component
    var errorCount = MxDataSet_emp_data.SrvErrCount("APP_COMPONENT");
    var i;
    for (i = 0; i < errorCount; i++) {
        $c.win.alert("[CODE: " + dts_registerIRDateSet.SrvErrCode("APP_COMPONENT", i) + "] " + dts_registerIRDateSet.SrvErrMsg("APP_COMPONENT", i));
    }

    // biz component
    var errorCount = dts_registerIRDateSet.SrvErrCount("BIZ_COMPONENT");
    var i;
    for (i = 0; i < errorCount; i++) {
        $c.win.alert("[CODE: " + dts_registerIRDateSet.SrvErrCode("BIZ_COMPONENT", i) + "] " + dts_registerIRDateSet.SrvErrMsg("BIZ_COMPONENT", i));
    }

    // action
    var errorCount = dts_registerIRDateSet.SrvErrCount("ACTION");
    var i;
    for (i = 0; i < errorCount; i++) {
        $c.win.alert("[CODE: " + dts_registerIRDateSet.SrvErrCode("ACTION", i) + "] " + dts_registerIRDateSet.SrvErrMsg("ACTION", i));
    }

    // core framework
    var errorCount = dts_registerIRDateSet.SrvErrCount("CORE_FRAMEWORK");
    var i;
    for (i = 0; i < errorCount; i++) {
        $c.win.alert("[CODE: " + dts_registerIRDateSet.SrvErrCode("CORE_FRAMEWORK", i) + "] " + dts_registerIRDateSet.SrvErrMsg("CORE_FRAMEWORK", i));
    }

    // web framework
    var errorCount = dts_registerIRDateSet.SrvErrCount("WEB_FRAMEWORK");
    var i;
    for (i = 0; i < errorCount; i++) {
        $c.win.alert("[CODE: " + dts_registerIRDateSet.SrvErrCode("WEB_FRAMEWORK", i) + "] " + dts_registerIRDateSet.SrvErrMsg("WEB_FRAMEWORK", i));
    }
};
scwin.isNumber = function(inputVal) {
    oneDecimal = false;
    var inputStr = inputVal.toString();
    var oneChar;
    for (var i = 0; i < inputStr.length; i++) {
        oneChar = inputStr.charAt(i);
        if (i == 0 && oneChar == "-") {
            continue;
        }
        if (oneChar == "." && !oneDecimal) {
            oneDecimal = true;
            continue;
        }
        if (oneChar < "0" || oneChar > "9") {
            return false;
        }
    }
    return true;
};
scwin.dateCheck = function() {
    if (scwin.vCurDate >= parseInt(edt_Date.getValue(), '10')) {
        $c.win.alert("[IR개최일자]를 현재일이후로 입력하세요");
        if (scwin.vIrSeq != "input") {
            edt_Date.setValue(scwin.readDate);
        }
        return false;
    }
};
scwin.timeCheck = function() {
    var startTime = $c.cp.valueOfIndex(hld_strt_tm_h, "value", hld_strt_tm_h.getSelectedIndex()) + $c.cp.valueOfIndex(hld_strt_tm_m, "value", hld_strt_tm_m.getSelectedIndex());
    var endTime = $c.cp.valueOfIndex(hld_end_tm_h, "value", hld_end_tm_h.getSelectedIndex()) + $c.cp.valueOfIndex(hld_end_tm_m, "value", hld_end_tm_m.getSelectedIndex());
    if (parseInt(startTime, '10') > parseInt(endTime, '10')) {
        $c.win.alert("[IR개최 시작시간은 종료시간다 작아야 합니다.]다시 입력해주세요");
        return false;
    }
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.img_com_srch_onclick = function() {
